-- Qianchuan fact table and source-owned field projection.
CREATE TABLE IF NOT EXISTS live_ad_hourly (
 route_id VARCHAR(128) NOT NULL,
 stat_hour DATETIME NOT NULL,
 dimension_hash CHAR(64) CHARACTER SET ascii NOT NULL,
 product_id VARCHAR(128) NOT NULL,
 room_id VARCHAR(128) NOT NULL,
 source VARCHAR(16) NOT NULL,
 account_id VARCHAR(128) NOT NULL,
 stat_cost DECIMAL(24,6) NULL,
 dimensions JSON NOT NULL,
 metrics JSON NOT NULL,
 observed_at DATETIME NOT NULL,
 PRIMARY KEY(route_id, stat_hour, dimension_hash),
 INDEX idx_ad_room_hour (room_id, stat_hour)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE OR REPLACE VIEW v_qianchuan_hourly AS
SELECT
  route_id,
  product_id,
  room_id,
  source,
  account_id,
  stat_hour,
  observed_at,
  dimensions AS raw_dimensions,
  metrics AS raw_metrics,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(dimensions, '$."stat_datetime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(dimensions, '$."stat_datetime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(dimensions, '$."stat_datetime"')) ELSE NULL END AS `stat_datetime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_day"')) ELSE NULL END AS `stat_time_day`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_hour"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_hour"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_time_hour"')) ELSE NULL END AS `stat_time_hour`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."start_date"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."start_date"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."start_date"')) ELSE NULL END AS `start_date`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."end_date"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."end_date"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."end_date"')) ELSE NULL END AS `end_date`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."time_granularity"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."time_granularity"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."time_granularity"')) ELSE NULL END AS `time_granularity`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."advertiser_id"')) ELSE NULL END AS `advertiser_id`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_name"')) ELSE NULL END AS `account_name`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."account_type"')) ELSE NULL END AS `account_type`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stat_platform"')) ELSE NULL END AS `stat_platform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."stats_authority"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stats_authority"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."stats_authority"')) ELSE NULL END AS `stats_authority`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_id"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_id"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_id"')) ELSE NULL END AS `aweme_id`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_show_id"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_show_id"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."aweme_show_id"')) ELSE NULL END AS `aweme_show_id`,
  NULL AS `aweme_nick_name`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."room_name"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."room_name"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."room_name"')) ELSE NULL END AS `room_name`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."stat_cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."stat_cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `stat_cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."show_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."show_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."show_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `show_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."ctr"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."ctr"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."ctr"')) AS DECIMAL(65,30)) ELSE NULL END AS `ctr`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cpm_platform"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpm_platform"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cpm_platform"')) AS DECIMAL(65,30)) ELSE NULL END AS `cpm_platform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."click_cnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."click_cnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."click_cnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `click_cnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."pay_order_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."pay_order_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."pay_order_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `pay_order_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."create_order_amount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_amount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_amount"')) AS DECIMAL(65,30)) ELSE NULL END AS `create_order_amount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."create_order_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `create_order_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."pay_order_amount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."pay_order_amount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."pay_order_amount"')) AS DECIMAL(65,30)) ELSE NULL END AS `pay_order_amount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."create_order_roi"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_roi"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."create_order_roi"')) AS DECIMAL(65,30)) ELSE NULL END AS `create_order_roi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."dy_follow"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."dy_follow"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."dy_follow"')) AS DECIMAL(65,30)) ELSE NULL END AS `dy_follow`,
