  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."prepay_order_count"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."prepay_order_count"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."prepay_order_count"')) AS DECIMAL(65,30)) ELSE NULL END AS `prepay_order_count`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."prepay_order_amount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."prepay_order_amount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."prepay_order_amount"')) AS DECIMAL(65,30)) ELSE NULL END AS `prepay_order_amount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."total_play"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."total_play"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."total_play"')) AS DECIMAL(65,30)) ELSE NULL END AS `total_play`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_duration_3s"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_duration_3s"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_duration_3s"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_duration_3s`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_25_feed_break"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_25_feed_break"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_25_feed_break"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_25_feed_break`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_50_feed_break"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_50_feed_break"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_50_feed_break"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_50_feed_break`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_75_feed_break"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_75_feed_break"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_75_feed_break"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_75_feed_break`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_over"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_over"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_over"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_over`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."play_over_rate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_over_rate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."play_over_rate"')) AS DECIMAL(65,30)) ELSE NULL END AS `play_over_rate`,
